-- 604: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 11 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_604_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_604_guard;
INSERT INTO _migration_604_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_041' AND NOT (q.topic_id IS 'topic_igcse_chem_analysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A solution is acidified with dilute nitric acid, then aqueous silver nitrate is added. A white precipitate forms. Which ion is present in the solution?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Sulfate, SO₄²⁻","B. Nitrate, NO₃⁻","C. Carbonate, CO₃²⁻","D. Chloride, Cl⁻"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A white precipitate of silver chloride after acidifying with dilute nitric acid confirms chloride ions. (Sulfate is tested with barium nitrate solution; the nitric acid destroys any carbonate, which would otherwise give a precipitate that dissolves in acid; nitrate gives no precipitate.) Therefore the correct answer is D: Chloride, Cl⁻.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_041' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_604_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_042' AND NOT (q.topic_id IS 'topic_igcse_chem_analysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What colour does a sodium compound produce in a flame test?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Yellow","B. Lilac","C. Brick-red","D. Green"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Sodium compounds give a bright yellow flame. (Lilac is potassium; brick-red is calcium; green is copper(II) or barium.) Therefore the correct answer is A: Yellow.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_042' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_604_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_043' AND NOT (q.topic_id IS 'topic_igcse_chem_analysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement correctly describes the test for ammonia gas?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It relights a glowing splint.","B. It turns damp red litmus paper blue.","C. It gives a squeaky pop with a lighted splint.","D. It turns limewater milky."]' AND q.correct_answer IS 'B' AND q.explanation IS 'Ammonia is the only common alkaline gas, so it turns damp red litmus paper blue. (Relighting a glowing splint is the oxygen test; a squeaky pop indicates hydrogen; milky limewater indicates carbon dioxide.) Therefore the correct answer is B: It turns damp red litmus paper blue..' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_043' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_604_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_044' AND NOT (q.topic_id IS 'topic_igcse_chem_analysis' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In paper chromatography, a spot travels 6.0 cm while the solvent front travels 8.0 cm. What is the Rf value of the spot?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1.33","B. 0.60","C. 0.75","D. 0.80"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Rf = distance travelled by the substance ÷ distance travelled by the solvent = 6.0 ÷ 8.0 = 0.75. (1.33 inverts the ratio, and Rf values can never exceed 1; 0.60 and 0.80 come from misreading the two distances.) Therefore the correct answer is C: 0.75.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_044' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_041', 'topic_igcse_chem_analysis', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'A solution is acidified with dilute nitric acid, then aqueous silver nitrate is added. A white precipitate forms. Which ion is present in the solution?', 'multiple_choice', NULL, '["A. Sulfate, SO₄²⁻","B. Nitrate, NO₃⁻","C. Carbonate, CO₃²⁻","D. Chloride, Cl⁻"]', 'D', 'A white precipitate of silver chloride after acidifying with dilute nitric acid confirms chloride ions. (Sulfate is tested with barium nitrate solution; the nitric acid destroys any carbonate, which would otherwise give a precipitate that dissolves in acid; nitrate gives no precipitate.) Therefore the correct answer is D: Chloride, Cl⁻.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
