INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_044', 'topic_igcse_chem_analysis', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'In paper chromatography, a spot travels 6.0 cm while the solvent front travels 8.0 cm. What is the Rf value of the spot?', 'multiple_choice', NULL, '["A. 1.33","B. 0.60","C. 0.75","D. 0.80"]', 'C', 'Rf = distance travelled by the substance ÷ distance travelled by the solvent = 6.0 ÷ 8.0 = 0.75. (1.33 inverts the ratio, and Rf values can never exceed 1; 0.60 and 0.80 come from misreading the two distances.) Therefore the correct answer is C: 0.75.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge');
